from typing import Any

import pydantic

from ...schemas.enums.EventType import EventTypeEnum
from ...schemas.rapi.base import BaseRapiResponseSchema


class Event(pydantic.BaseModel):
    eventId: int
    type: EventTypeEnum
    payload: dict[str, Any]


class EventsPollResultsSchema(pydantic.BaseModel):
    lastEventId: int
    events: list[Event]


class EventsPollResponseSchema(BaseRapiResponseSchema):
    results: EventsPollResultsSchema


class EventSubscribeResponseSchema(BaseRapiResponseSchema): ...
